const main=document.querySelector('main'),nav=document.querySelector('nav'),menu=document.querySelector('#menu'),viewer=document.querySelector('#viewer');
const asset=n=>'assets/'+encodeURIComponent(n);
const image=(w,n=0)=>`<img src="${asset(w.images[n])}" alt="${w.alt}${n?' Detail view.':''}" ${n?'loading="lazy"':''}>`;
const card=w=>`<a class="card" href="#work/${w.id}">${image(w)}<div class="caption"><span>${w.title}</span><span class="year">${w.year}</span></div></a>`;
menu.onclick=()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav.classList.toggle('open',open);menu.querySelector('span').textContent=open?'−':'+'};
const exhibitionViews=[
{file:'exhibition-cyanotype.jpg',alt:'Kiko Thomas’s architectural cyanotype and street painting in the gallery, with a sculpture on a plinth in the foreground.',caption:'Kiko Thomas · Cyanotype and painting, installation view'},
{file:'exhibition-gallery.jpg',alt:'Kiko Thomas’s paintings along the gallery wall, with the blue architectural cyanotype at the far end and sculptures in the shared exhibition space.',caption:'Where One Does Not Belong · Installation view'},
{file:'exhibition-painting-wall.jpg',alt:'A painting by Kiko Thomas in the center of a gallery wall, flanked by two photographs.',caption:'Kiko Thomas · Painting, installation view'},
{file:'exhibition-wall-detail.png',alt:'A small mixed-media wall work alongside a photograph of a red phone and a sculpture in the shared exhibition space.',caption:'Where One Does Not Belong · Installation view'},
{file:'where-one-does-not-belong-installation.jpg',alt:'Gallery installation with Kiko Thomas’s aircraft painting on the wall and sculptures in the shared exhibition space.',caption:'Where One Does Not Belong · Installation view'}
];
const exhibitionFigure=(v,i)=>`<figure class="exhibition-image"><button data-exhibition="${i}" aria-label="Enlarge exhibition view ${i+1}"><img src="${asset(v.file)}" alt="${v.alt}" ${i?'loading="lazy"':''}></button><figcaption><span>${v.caption}</span><span>${String(i+1).padStart(2,'0')} / 05</span></figcaption></figure>`;
function openViewer(src,alt,caption){viewer.querySelector('img').src=src;viewer.querySelector('img').alt=alt;viewer.querySelector('p').textContent=caption;viewer.showModal()}
function render(){const route=location.hash.slice(1)||'home';nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.querySelector('span').textContent='+';document.querySelectorAll('nav a').forEach(a=>{a.removeAttribute('aria-current');if(route.startsWith(a.hash.slice(1)))a.setAttribute('aria-current','page')});
if(route==='home'||route==='shows/where-one-does-not-belong'){main.innerHTML=`<section class="exhibition">${route.startsWith("shows/")?'<a class="back" href="#shows">← All shows</a>':''}<div class="artist-intro"><p>Kiko Thomas is an interdisciplinary artist based in Los Angeles.</p><a href="#about">About the artist ↗</a></div><div class="exhibition-title"><div><p class="eyebrow">Previous show · 2026</p><h1>Where One<br>Does Not Belong</h1></div><div class="exhibition-meta">MM/DD/YYYY Gallery<br>CalArts at The Reef, Los Angeles<br><a class="text-link" href="${route==='home'?'#shows/where-one-does-not-belong':'#shows'}">${route==='home'?'View show →':'All shows →'}</a></div></div>${exhibitionFigure(exhibitionViews[0],0)}<div class="exhibition-story"><div><p class="eyebrow">Kiko Thomas</p><h2>Painting, place,<br>and belonging.</h2></div><div><p>Paintings and a large-scale architectural cyanotype by Kiko Thomas, presented in <em>Where One Does Not Belong</em>, a group exhibition with Kyle Slevira and Jake Thornton.</p><a class="text-link" href="#work">Explore Kiko’s works →</a></div></div><section class="installation-views" aria-label="Exhibition views"><div class="installation-heading"><h2>Exhibition views</h2><span class="eyebrow">Where One Does Not Belong</span></div>${exhibitionViews.slice(1).map((v,i)=>exhibitionFigure(v,i+1)).join('')}</section><details class="credits"><summary>Exhibition information & credits</summary><dl><dt>Artists</dt><dd>Kiko Thomas, Kyle Slevira, Jake Thornton</dd><dt>Venue</dt><dd>MM/DD/YYYY Gallery, Suite 1207<br>CalArts at The Reef<br>1933 S Broadway, Los Angeles</dd><dt>Exhibition dates</dt><dd>—</dd><dt>Curator</dt><dd>—</dd><dt>Photography</dt><dd>—</dd></dl><p><a href="https://indd.adobe.com/embed/64829b25-acb1-4557-8adf-832c4a547294?allowFullscreen=true&startpage=1" target="_blank" rel="noopener">View exhibition publication ↗</a></p></details></section>`;main.querySelectorAll('[data-exhibition]').forEach(b=>b.onclick=()=>{const v=exhibitionViews[Number(b.dataset.exhibition)];openViewer(asset(v.file),v.alt,v.caption)})}
else if(route==='shows'){main.innerHTML=`<div class="work-head"><h1>Shows</h1><span class="eyebrow">Previous shows</span></div><div class="shows-list"><a class="show-card" href="#shows/where-one-does-not-belong"><img src="${asset(exhibitionViews[0].file)}" alt="${exhibitionViews[0].alt}"><div><p class="eyebrow">2026 · Group exhibition</p><h2>Where One Does Not Belong</h2><p>MM/DD/YYYY Gallery<br>CalArts at The Reef, Los Angeles</p><span class="text-link">View show →</span></div></a></div>`}
else if(route==='work'){main.innerHTML=`<div class="work-head"><h1>Selected works</h1><span class="eyebrow">2025 — 2026</span></div><div class="grid">${works.map(card).join('')}</div>`}
else if(route.startsWith('work/')){const i=works.findIndex(w=>w.id===route.split('/')[1]);if(i<0){location.hash='work';return}const w=works[i];main.innerHTML=`<a class="back" href="#work">← All works</a><article class="detail"><div class="pictures">${w.images.map((n,j)=>`<figure><button data-zoom="${j}" aria-label="Enlarge ${w.title}${j?' detail':''}">${image(w,j)}</button><figcaption>${j?'Detail view':'Installation / artwork view'} · Click to enlarge</figcaption></figure>`).join('')}</div><aside><span class="eyebrow">Selected work · ${String(i+1).padStart(2,'0')}</span><h1>${w.title}</h1><span class="year">${w.year}</span><div class="metadata"><p>${w.medium}</p><p>${w.dimensions}</p></div><div class="work-description"><h2>About the work</h2><p>${w.description||'—'}</p></div></aside></article><div class="detail-nav"><a href="#work/${works[(i+works.length-1)%works.length].id}">← Previous work</a><a href="#work">Index</a><a href="#work/${works[(i+1)%works.length].id}">Next work →</a></div>`;main.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{openViewer(asset(w.images[Number(b.dataset.zoom)]),w.alt,w.title)})}
else if(route==='about'){main.innerHTML=`<section class="prose"><p class="eyebrow">Artist information</p><h1>Kiko Thomas</h1><p>Kiko Thomas is an educator and multidisciplinary artist based in Los Angeles.</p><p>He holds a BFA from the University of California San Diego and an MFA from the California Institute of the Arts. He is a recipient of the Charles Gaines Fellowship.</p><a class="back" href="#work">Explore selected works →</a></section>`}
else {location.hash='home';return}
document.title=(route==='shows'?'Shows — ':route.startsWith('shows/')?'Where One Does Not Belong — ':route.startsWith('work/')?works.find(w=>w.id===route.split('/')[1])?.title+' — ':'')+'Kiko Thomas';window.scrollTo(0,0)}
document.querySelector('#close').onclick=()=>viewer.close();viewer.addEventListener('click',e=>{if(e.target===viewer)viewer.close()});window.addEventListener('hashchange',render);render();
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView()});
